document.querySelectorAll('.rank-row').forEach(row=>row.addEventListener('click',()=>{const n=row.dataset.province,node=paths.nodes().find(p=>p.dataset.name===n);selectProvince(n,node);jsonScrollToClientPanel()}));
function jsonScrollToClientPanel(){var cp=document.getElementById('clientPanel');if(!cp)return;var r=cp.getBoundingClientRect();if(r.top>window.innerHeight*0.55){window.scrollTo({top:r.top+window.scrollY-70,behavior:'smooth'})}}
function renderCustomers(){let rows=CUSTOMERS.filter(x=>!activeProvince||x.province===activeProvince);if(clientFilter==='threeA')rows=rows.filter(x=>x.threeA);if(clientFilter==='signed')rows=rows.filter(x=>x.statuses.includes('签约'));if(clientFilter==='trial')rows=rows.filter(x=>x.statuses.includes('试用'));rows=rows.slice().sort((a,b)=>(b.benchmark?1:0)-(a.benchmark?1:0));document.getElementById('clientTitle').textContent=(activeProvince||'全国')+'客户名单';const visible=showAllClients?rows:rows.slice(0,12);document.getElementById('clientGrid').innerHTML=visible.length?visible.map(x=>`<article class="client-card ${x.threeA?'three-a':''} ${x.benchmark?'benchmark':''}"><h4>${x.name}</h4><div class="client-meta">${x.threeA?'<span class="client-tag grade">三甲</span>':''}${x.rankTier?`<span class="client-tag rank">复旦${x.rankTier}</span>`:''}${x.statuses.map(s=>`<span class="client-tag ${s==='签约'?'signed':'trial'}">${s}</span>`).join('')}<span class="client-tag">${x.province}</span></div>${x.analysisKnown?`<div class="client-analysis"><span>后台累计切片</span><b>${fmt(x.analysis)}条</b></div>`:''}</article>`).join(''):'<div class="client-empty">当前筛选条件下暂无已核验客户</div>';const more=document.getElementById('clientMore');more.style.display=rows.length>12?'block':'none';more.textContent=showAllClients?'收起客户名单':`展开全部客户（${rows.length}家）`}
document.querySelectorAll('.client-filter[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{clientFilter=btn.dataset.filter;showAllClients=false;document.querySelectorAll('.client-filter[data-filter]').forEach(x=>x.classList.toggle('active',x===btn));renderCustomers()}));
document.getElementById('clearProvince').addEventListener('click',()=>{activeProvince='';paths.classed('active',false);document.getElementById('pname').textContent='全国';document.getElementById('pdesc').textContent='展示全部可核验客户明细';document.getElementById('ptotal').textContent=Object.values(PROVINCES).reduce((a,b)=>a+b.total,0);document.getElementById('pvolume').textContent=Object.values(PROVINCES).reduce((a,b)=>a+b.threeA,0);document.getElementById('pstage').textContent=`${Object.values(PROVINCES).reduce((a,b)=>a+b.signed,0)} / ${Object.values(PROVINCES).reduce((a,b)=>a+b.trial,0)}`;document.getElementById('puploads').textContent=Object.values(PROVINCES).reduce((a,b)=>a+(b.analysis||0),0).toLocaleString('en-US');renderCustomers()});document.getElementById('clientMore').addEventListener('click',()=>{showAllClients=!showAllClients;renderCustomers()});
renderCustomers();
